<script setup>
import { computed, ref } from 'vue'
const props = defineProps({ applications: { type: Array, default: () => [] }, loading: Boolean })
const emit = defineEmits(['review', 'refresh'])
const activeTab = ref('pending')
const pending = computed(() => (Array.isArray(props.applications) ? props.applications : []).filter((item) => item.status === 'pending'))
const history = computed(() => (Array.isArray(props.applications) ? props.applications : []).filter((item) => item.status !== 'pending'))
</script>

<template>
  <section class="review-page"><article class="panel"><div class="review-toolbar"><div class="review-tabs"><button :class="{ active: activeTab === 'pending' }" type="button" @click="activeTab = 'pending'">待审核申请 <span>{{ pending.length }}</span></button><button :class="{ active: activeTab === 'history' }" type="button" @click="activeTab = 'history'">已处理申请 <span>{{ history.length }}</span></button></div><button class="text-button" type="button" @click="emit('refresh')">刷新</button></div><div v-if="activeTab === 'pending'" class="tab-panel"><div v-if="!pending.length" class="empty"><strong>当前没有待审核申请</strong><span>新的工作空间加入申请会显示在这里。</span></div><div v-for="application in pending" :key="application.id" class="review-row"><div><strong>{{ application.username }}</strong><small>提交于 {{ new Date(application.created_at).toLocaleString() }}</small></div><span class="default-role">批准后授予工作空间默认角色</span><div class="actions"><button class="approve" :disabled="loading" type="button" @click="emit('review', { id: application.id, approve: true })">批准</button><button class="reject" :disabled="loading" type="button" @click="emit('review', { id: application.id, approve: false })">拒绝</button></div></div></div><div v-else class="tab-panel"><ul class="history"><li v-for="application in history" :key="application.id"><span><strong>{{ application.username }}</strong><small>{{ new Date(application.created_at).toLocaleString() }}</small></span><em :class="application.status">{{ application.status === 'approved' ? '已批准' : '已拒绝' }}</em></li><li v-if="!history.length" class="muted">暂无已处理记录。</li></ul></div></article></section>
</template>

<style scoped>
